def semver_sort(versions):
    def parse_key(v):
        # strip build metadata
        core = v.split('+', 1)[0]
        if '-' in core:
            main, pre = core.split('-', 1)
        else:
            main, pre = core, None
        major, minor, patch = (int(x) for x in main.split('.'))
        if pre is None:
            has_pre_flag = 1  # no prerelease sorts after
            pre_tuple = ()
        else:
            has_pre_flag = 0
            ids = pre.split('.')
            parsed_ids = []
            for ident in ids:
                if ident.isdigit():
                    parsed_ids.append((0, int(ident)))
                else:
                    parsed_ids.append((1, ident))
            pre_tuple = tuple(parsed_ids)
        return (major, minor, patch, has_pre_flag, pre_tuple)

    return sorted(versions, key=parse_key)

